#!/usr/bin/env python3
"""dwimsy.meta.unbundle - Standalone self-extracting payload and in-memory asset provider.

Project Homepage: https://github.com/f-fix/dwimsy
Version: 0.1.6.21-dev (2026-08-28)

dwimsy - retrocomputing media preservation, demodulation, restoration, and preparation.
A modular toolkit for vintage computer tapes, disks, ROMs, and audio captures.

This standalone script is also distributed as dwimsy_0.1.6.21-dev.py.

Bundle Basics:
To use the embedded dwimsy CLI directly from the bundle:
  python3 dwimsy_0.1.6.21-dev.py dwimsy --help
  python3 dwimsy_0.1.6.21-dev.py dwimsy --version
  python3 dwimsy_0.1.6.21-dev.py dwimsy readme
  python3 dwimsy_0.1.6.21-dev.py dwimsy license
  python3 dwimsy_0.1.6.21-dev.py dwimsy changelog

To extract the repository tree to disk:
  python3 dwimsy_0.1.6.21-dev.py meta unbundle /path/to/target --deps
"""

